func ResolveEventDateHCM(tsMs int64, fallback time.Time) string {
	if fallback.IsZero() {
		fallback = time.Now()
	}
	fbHCM := fallback.In(locHCM)
	fbDate := fbHCM.Format("2006-01-02")
	if tsMs <= 0 {
		return fbDate
	}

